/**
 * Simple in-memory "database" for storing named entries.
 */

class SimpleDatabase {
  /**
   * @param {Array<{name: string, timestamp: number, type: string}>} [initialEntries]
   */
  constructor(initialEntries = []) {
    /** @type {Array<{id: string, name: string, timestamp: number, type: string}>} */
    this.entries = initialEntries;
  }

  /**
   * Add a new entry and return it with a generated id.
   * @param {string} name
   * @param {string} type
   * @returns {{id: string, name: string, timestamp: number, type: string}}
   */
  add(name, type) {
    const entry = {
      id: Math.random().toString(36).substring(2, 10),
      name,
      timestamp: Date.now(),
      type,
    };
    this.entries.push(entry);
    return entry;
  }

  /**
   * Get a single entry by its id.
   * @param {string} id
   * @returns {{id: string, name: string, timestamp: number, type: string} | undefined}
   */
  get(id) {
    return this.entries.find((entry) => entry.id === id);
  }

  /**
   * List all entries.
   * @returns {Array<{id: string, name: string, timestamp: number, type: string}>}
   */
  list() {
    return [...this.entries];
  }
}

