/**
 * Utility functions for random data generation.
 */

/**
 * Returns a random hex color string (e.g., "#a3f2b1").
 */
function randomColor() {
  const hex = Math.floor(Math.random() * 16777215).toString(16);
  return `#${hex.padStart(6, '0')}`;
}

/**
 * Picks a random item from the given array.
 * @param {Array} arr - The source array.
 * @returns {*} A random element from the array.
 */
function randomQuote(arr) {
  if (!Array.isArray(arr) || arr.length === 0) {
    return undefined;
  }
  return arr[Math.floor(Math.random() * arr.length)];
}

/**
 * Returns a short random string (8 characters, base62).
 * @returns {string}
 */
function generateId() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 8; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
}

module.exports = { randomColor, randomQuote, generateId };

